-- The catalogue check of the control-plane line.
-- GENERATED by `pnpm --filter @engine/db test` (with ENGINE_DB_WRITE=1) from control-objects.json
-- and the list of migration files. Do not edit by hand.
--
-- Run it against a database after the control-plane migrations. It changes nothing. It raises one
-- error that lists every problem: something missing, something nobody listed, or a function that
-- someone other than the signed-in role can call.

do $catalogue$
declare
  v_problems text[] := array[]::text[];
  v_tables constant text[] := array[
    'audit_log',
    'engine_releases',
    'grantable_features',
    'provisioning_runs',
    'schema_migrations',
    'superusers',
    'support_access_grants',
    'tenant_domains',
    'tenant_entitlements',
    'tenant_infrastructure',
    'tenant_schema_state',
    'tenants',
    'usage_totals'
  ]::text[];
  v_private_functions constant text[] := array[
    'audit_log_guard',
    'bootstrap_first_superuser',
    'reason',
    'require_superuser',
    'support_grant_guard',
    'tenant_for_change',
    'write_audit'
  ]::text[];
  v_api_functions constant text[] := array[
    'audit_log_read',
    'engine_release_record',
    'engine_release_withdraw',
    'provisioning_run_finish',
    'provisioning_run_start',
    'provisioning_step_record',
    'superuser_add',
    'superuser_revoke',
    'superusers_list',
    'support_grant_close',
    'support_grant_delivery',
    'support_grant_open',
    'support_grants_list',
    'support_reads_record',
    'tenant_create',
    'tenant_domain_add',
    'tenant_domain_remove',
    'tenant_entitlements_delivered',
    'tenant_entitlements_set',
    'tenant_get',
    'tenant_infrastructure_set',
    'tenant_schema_state_record',
    'tenant_set_status',
    'tenants_list',
    'usage_totals_read',
    'usage_totals_record',
    'whoami'
  ]::text[];
  v_triggers constant text[] := array[
    'audit_log.audit_log_no_change',
    'audit_log.audit_log_no_truncate',
    'support_access_grants.support_access_grants_guard',
    'support_access_grants.support_access_grants_no_truncate'
  ]::text[];
  v_versions constant text[] := array[
    '0001',
    '0002',
    '0003'
  ]::text[];
  v_nothing constant text[] := array[]::text[];
begin
  -- 1. Exactly the listed objects, no more and no fewer.
  v_problems := v_problems || coalesce((
    select array_agg('table not expected: ' || a.name order by a.name)
      from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'control'::regnamespace and c.relkind in ('r', 'p')) a
     where not (a.name = any (v_tables))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('table missing: ' || e.name order by e.name)
      from unnest(v_tables) e(name)
     where not exists (select 1 from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'control'::regnamespace and c.relkind in ('r', 'p')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('view or other relation in the private schema not expected: ' || a.name order by a.name)
      from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'control'::regnamespace and c.relkind in ('v', 'm', 'f')) a
     where not (a.name = any (v_nothing))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('view or other relation in the private schema missing: ' || e.name order by e.name)
      from unnest(v_nothing) e(name)
     where not exists (select 1 from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'control'::regnamespace and c.relkind in ('v', 'm', 'f')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('relation in the public schema not expected: ' || a.name order by a.name)
      from (select c.relname::text as name from pg_catalog.pg_class c
       where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'v', 'm', 'f', 'S')
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = c.oid and d.deptype = 'e')) a
     where not (a.name = any (v_nothing))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('relation in the public schema missing: ' || e.name order by e.name)
      from unnest(v_nothing) e(name)
     where not exists (select 1 from (select c.relname::text as name from pg_catalog.pg_class c
       where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'v', 'm', 'f', 'S')
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = c.oid and d.deptype = 'e')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private function not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p where p.pronamespace = 'control'::regnamespace) f) a
     where not (a.name = any (v_private_functions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private function missing: ' || e.name order by e.name)
      from unnest(v_private_functions) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p where p.pronamespace = 'control'::regnamespace) f) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f) a
     where not (a.name = any (v_api_functions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function missing: ' || e.name order by e.name)
      from unnest(v_api_functions) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('trigger not expected: ' || a.name order by a.name)
      from (select c.relname::text || '.' || t.tgname::text as name
        from pg_catalog.pg_trigger t
        join pg_catalog.pg_class c on c.oid = t.tgrelid
       where not t.tgisinternal and c.relnamespace in ('control'::regnamespace, 'public'::regnamespace)) a
     where not (a.name = any (v_triggers))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('trigger missing: ' || e.name order by e.name)
      from unnest(v_triggers) e(name)
     where not exists (select 1 from (select c.relname::text || '.' || t.tgname::text as name
        from pg_catalog.pg_trigger t
        join pg_catalog.pg_class c on c.oid = t.tgrelid
       where not t.tgisinternal and c.relnamespace in ('control'::regnamespace, 'public'::regnamespace)) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('migration not expected: ' || a.name order by a.name)
      from (select m.version as name from control.schema_migrations m) a
     where not (a.name = any (v_versions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('migration missing: ' || e.name order by e.name)
      from unnest(v_versions) e(name)
     where not exists (select 1 from (select m.version as name from control.schema_migrations m) a where a.name = e.name)), array[]::text[]);

  -- 2. Who can call what. The signed-in role: exactly the listed functions. A visitor, the
  --    service role and "everyone": nothing at all, in either schema.
  v_problems := v_problems || coalesce((
    select array_agg('function the signed-in role can call not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('authenticated', f.oid, 'execute')) a
     where not (a.name = any (v_api_functions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function the signed-in role can call missing: ' || e.name order by e.name)
      from unnest(v_api_functions) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('authenticated', f.oid, 'execute')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function a visitor can call not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('anon', f.oid, 'execute')) a
     where not (a.name = any (v_nothing))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function a visitor can call missing: ' || e.name order by e.name)
      from unnest(v_nothing) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('anon', f.oid, 'execute')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function the service role can call not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('service_role', f.oid, 'execute')) a
     where not (a.name = any (v_nothing))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function the service role can call missing: ' || e.name order by e.name)
      from unnest(v_nothing) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('service_role', f.oid, 'execute')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function open to every role not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where exists (select 1 from pg_catalog.aclexplode(f.proacl) g where g.grantee = 0)) a
     where not (a.name = any (v_nothing))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function open to every role missing: ' || e.name order by e.name)
      from unnest(v_nothing) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where exists (select 1 from pg_catalog.aclexplode(f.proacl) g where g.grantee = 0)) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private function open to every role not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p where p.pronamespace = 'control'::regnamespace) f where exists (select 1 from pg_catalog.aclexplode(f.proacl) g where g.grantee = 0)) a
     where not (a.name = any (v_nothing))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private function open to every role missing: ' || e.name order by e.name)
      from unnest(v_nothing) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p where p.pronamespace = 'control'::regnamespace) f where exists (select 1 from pg_catalog.aclexplode(f.proacl) g where g.grantee = 0)) a where a.name = e.name)), array[]::text[]);

  if pg_catalog.array_length(v_problems, 1) > 0 then
    raise exception 'CATALOGUE CHECK FAILED (% problems): %',
      pg_catalog.array_length(v_problems, 1), pg_catalog.array_to_string(v_problems, '; ');
  end if;
end;
$catalogue$;
